mapper.select:
select * from grid_spot_user_assets
where user_id = #{userId,jdbcType=BIGINT}

    and grid_spot_order_id = #{gridId,jdbcType=BIGINT}


    and currency =#{currency,jdbcType=VARCHAR}

SELECT a.*
FROM grid_spot_user_assets a
LEFT JOIN grid_spot_order o ON a.grid_spot_order_id = o.id
WHERE a.user_id = #{userId,jdbcType=BIGINT}

    and a.currency = #{currency,jdbcType=VARCHAR}

and o.`status` in (0, 1, 2, 3)
